"                         <button
                           onClick={() => {
                             executeBillingAction('preview', 'View Bill Preview', handleShowBillPreview);
                           }}
                           className="hover:text-slate-100 transition-colors"
                         >
                           <Eye size={20} strokeWidth={2.5} />
                         </button>
                         <button
                           onClick={() => {
                             executeBillingAction('allow_draft_bill_printing', 'Print Draft Bill', () => handleCheckout('PRINT'));
                           }}
                           className="transition-colors hover:text-slate-100"
                         >
                           <Printer size={20} strokeWidth={2.5} />
                         </button>
                         <button
                           onClick={() => {
                             executeBillingAction('add_discount', 'Apply Discount', () => setIsDiscountModalOpen(true));
                           }}
                           className="hover:text-slate-100 transition-colors"
                         >
                           <Tag size={20} strokeWidth={2.5} />
                         </button>
                         <button
                           onClick={() => {
                             executeBillingAction('add_charges', 'Apply Charges', () => setIsChargesModalOpen(true));
                           }}
                           className="hover:text-slate-100 transition-colors"
                         >
                           <Coins size={20} strokeWidth={2.5} />
                         </button>"
